import { after } from 'next/server';
import { headers } from 'next/headers';

// Simulated analytics service
async function logPageView(data: {
  page: string;
  userAgent: string;
  timestamp: string;
}) {
  // In a real app, this would send data to an analytics service
  console.log('Analytics logged:', data);
  // Simulate network delay
  await new Promise(resolve => setTimeout(resolve, 100));
}

export default async function Home() {
  // Read request data BEFORE the after() callback
  // This is required for Server Components
  const headersList = await headers();
  const userAgent = headersList.get('user-agent') || 'unknown';
  const timestamp = new Date().toISOString();

  // Schedule analytics logging AFTER the response is sent
  // This does not block the response to the user
  after(async () => {
    await logPageView({
      page: '/home',
      userAgent,
      timestamp,
    });
  });

  return (
    <main>
      <h1>Welcome</h1>
      <p>This page logs views to analytics without blocking the response.</p>
      <p>The logging happens after the page is sent to you!</p>
    </main>
  );
}

